const context = options.contextData;
	const viewmodel = options.contextData.viewmodel;
	const selectedElement = context.selectedElement;
	const editLevel = context.documentationEnums.EditLevels.FullAllow;
	const modelCursor = viewmodel.Cursor();
	const resultSettings = {
		hidden: true
	};

	if (selectedElement && selectedElement.is('ArasTextXmlSchemaElement') && selectedElement === modelCursor.commonAncestor) {
		resultSettings.hidden = !(viewmodel.IsEqualEditableLevel(editLevel) || selectedElement.GetSelectedLinksCount());
	}

	return resultSettings;
